"""Rigs a mesh generated by Hyper3D Rodin so it can walk and idle like the procedural models.

    blender -b --python models-src/rodin_rig.py -- rodin.glb out.glb models-src/rodin/<npc_id>.json

The Rodin mesh is static: it is scaled to `height_m`, stood on the floor, decimated, its textures are reduced to a
single base-colour map, then it is skinned to the same bone set as chargen (Root..Head_end, arms, legs) and given
the same Idle and Walk clips. The JSON config holds what is specific to one figure: its height, the joint positions
(fractions of the height; metres per side when the figure stands asymmetrically), the held item and whether it has a skirt.
"""
import json
import math
import os
import sys

import bmesh
import bpy
from mathutils import Vector

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

from chargen import humanoid  # noqa: E402
from chargen.core import reset_scene  # noqa: E402

args = sys.argv[sys.argv.index("--") + 1:]
SRC, OUT = args[0], os.path.abspath(args[1])
CONFIG = json.load(open(args[2])) if len(args) > 2 else {}
NAME = CONFIG.get("name", os.path.splitext(os.path.basename(OUT))[0])
HEIGHT = CONFIG.get("height", 2.0)
TRIS = CONFIG.get("tris", 14000)
TEX = CONFIG.get("tex", 1024)
CENTRE = CONFIG.get("centre", "median")  # x of the centre line: median of the vertices, or the middle of the bounding box
SKIRT = CONFIG.get("skirt", False)
# Height of the skirt's hem in metres. Only cloth above it keeps part of its weight on the hips; bare legs
# below it follow the legs alone (null: the whole lower leg counts as skirt, as for a long robe).
SKIRT_HEM = CONFIG.get("skirt_hem")
# Where the foot's weight fades into the shin, in metres above the ankle joint. A wide band makes the lower
# shin turn with the foot and bend like rubber; sandal straps need only a few centimetres.
ANKLE_BLEND = CONFIG.get("ankle_blend", [0.02, 0.13])
STRIDE = CONFIG.get("stride")
ARM_SWING = CONFIG.get("arm_swing", 1.0)
ARM_SWING_SIDES = CONFIG.get("arm_swing_sides", {})  # {"L": factor, "R": factor}: a hand fused with the clothing barely swings
SPATIAL = CONFIG.get("spatial_smooth")  # [radius below the hips, radius above] in metres, or null
STAR_DISC = CONFIG.get("star_disc")  # {"radius": m, "points": 8, "lift": m above the top of the head}
SMOOTH = CONFIG.get("smooth_regions")  # [{"x": [lo, hi], "y": ..., "z": ..., "iterations": n, "factor": f}, ...] in metres
QUIVER = CONFIG.get("quiver")  # {"z": metres up the back, "x": metres, "length": m, "arrows": n}
FACE = CONFIG.get("face")  # {"eyes": [[x, y, z], [x, y, z]], "mouth": [x, y, z]} in metres: blink and mouth shapes
HEAD_END_Z = CONFIG.get("head_end_z")  # name plate bone height in metres, when an ornament rises above the head
INFLUENCES = CONFIG.get("influences", 4)  # bones per vertex; a long skirt over two legs needs more than 4
HELD = CONFIG.get("held")  # {"bone": "Hand_R", "boxes": [{"x": [lo, hi], "y": [lo, hi], "z": [lo, hi]}, ...]}; a null bound is open

# joint -> (x as a fraction of height from the centre line, z as a fraction of height); x is the character's left (+X)
JOINTS = {
    "shoulder": (0.08, 0.75), "elbow": (0.10, 0.60), "wrist": (0.11, 0.48), "hand": (0.115, 0.43),
    "hip": (0.045, 0.525), "knee": (0.05, 0.275), "ankle": (0.045, 0.045), "toe": (0.045, 0.015),
}
JOINTS.update({k: tuple(v) for k, v in CONFIG.get("joints", {}).items()})
# an asymmetric figure (contrapposto): x of each joint in metres, (left, right)
SIDE_X = {k: tuple(v) for k, v in CONFIG.get("side_x", {}).items()}
# y of a joint in metres (negative = forward), for arms held in front of the body
JOINT_Y = CONFIG.get("joint_y", {})


def import_mesh():
    reset_scene()
    bpy.ops.import_scene.gltf(filepath=SRC)
    meshes = [o for o in bpy.context.scene.objects if o.type == "MESH"]
    body = max(meshes, key=lambda o: len(o.data.polygons))
    for o in list(bpy.context.scene.objects):
        if o is not body:
            bpy.data.objects.remove(o, do_unlink=True)
    body.parent = None
    bpy.context.view_layer.objects.active = body
    body.select_set(True)
    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)
    return body


def normalise(body):
    zs = [v.co.z for v in body.data.vertices]
    scale = HEIGHT / (max(zs) - min(zs))
    for v in body.data.vertices:
        v.co *= scale
    xs = sorted(v.co.x for v in body.data.vertices)
    ys = [v.co.y for v in body.data.vertices]
    dx = xs[len(xs) // 2] if CENTRE == "median" else (xs[0] + xs[-1]) / 2
    dz = min(v.co.z for v in body.data.vertices)
    dy = (max(ys) + min(ys)) / 2
    for v in body.data.vertices:
        v.co -= Vector((dx, dy, dz))
    body.data.update()


def is_held(co):
    """Held item (the mace): inside any of the configured boxes."""
    if not HELD:
        return False
    for box in HELD["boxes"]:
        if all((lo is None or c >= lo) and (hi is None or c <= hi) for c, (lo, hi) in zip(co, (box.get("x", (None, None)), box.get("y", (None, None)), box.get("z", (None, None))))):
            return True
    return False


def weld(body):
    """The generated mesh is split along UV seams. Decimating it as it is pulls the two sides of a seam apart and opens
    cracks, so vertices at the same position are joined first (the UVs live on the face corners and are kept)."""
    bm = bmesh.new()
    bm.from_mesh(body.data)
    bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=0.0005)
    bm.to_mesh(body.data)
    bm.free()
    body.data.update()


def smooth_regions(body):
    """Generated cloth sometimes has flat, boxy patches; smooth the configured regions a little."""
    if not SMOOTH:
        return
    bm = bmesh.new()
    bm.from_mesh(body.data)
    for region in SMOOTH:
        def inside(co):
            return all((lo is None or c >= lo) and (hi is None or c <= hi) for c, (lo, hi) in zip(co, (region.get("x", (None, None)), region.get("y", (None, None)), region.get("z", (None, None)))))
        verts = [v for v in bm.verts if inside(v.co)]
        for _ in range(region.get("iterations", 6)):
            bmesh.ops.smooth_vert(bm, verts=verts, factor=region.get("factor", 0.5), use_axis_x=True, use_axis_y=True, use_axis_z=True)
    bm.to_mesh(body.data)
    bm.free()
    body.data.update()


def decimate(body):
    """Decimation bridges the thin gap between the mace and the skirt, so the mace is reduced on its own."""
    weld(body)
    smooth_regions(body)
    before = len(body.data.polygons)
    if before <= TRIS:
        return body
    if not HELD:
        mod = body.modifiers.new("dec", "DECIMATE")
        mod.ratio = TRIS / before
        bpy.ops.object.modifier_apply(modifier=mod.name)
        return body
    bpy.ops.object.mode_set(mode="EDIT")
    bpy.ops.mesh.select_all(action="DESELECT")
    bpy.ops.object.mode_set(mode="OBJECT")
    for poly in body.data.polygons:
        poly.select = all(is_held(body.data.vertices[i].co) for i in poly.vertices)
    bpy.ops.object.mode_set(mode="EDIT")
    bpy.ops.mesh.separate(type="SELECTED")
    bpy.ops.object.mode_set(mode="OBJECT")
    parts = [o for o in bpy.context.scene.objects if o.type == "MESH"]
    held = min(parts, key=lambda o: len(o.data.polygons)) if len(parts) > 1 else None
    for o in parts:
        keep = TRIS * 0.08 if o is held else TRIS - (TRIS * 0.08 if held else 0)
        if len(o.data.polygons) > keep:
            mod = o.modifiers.new("dec", "DECIMATE")
            mod.ratio = keep / len(o.data.polygons)
            bpy.context.view_layer.objects.active = o
            bpy.ops.object.modifier_apply(modifier=mod.name)
    if held is not None:
        bpy.ops.object.select_all(action="DESELECT")
        body.select_set(True)
        held.select_set(True)
        bpy.context.view_layer.objects.active = body
        bpy.ops.object.join()
    return body


def simplify_material(body):
    """One material with only a base-colour texture of TEX px; the original maps weigh several MiB."""
    src = body.data.materials[0]
    image = next(n.image for n in src.node_tree.nodes if n.type == "TEX_IMAGE" and "diffuse" in n.image.name)
    image.scale(TEX, TEX)
    mat = bpy.data.materials.new("rodin_body")
    mat.use_nodes = True
    nodes, links = mat.node_tree.nodes, mat.node_tree.links
    bsdf = nodes["Principled BSDF"]
    tex = nodes.new("ShaderNodeTexImage")
    tex.image = image
    links.new(tex.outputs["Color"], bsdf.inputs["Base Color"])
    bsdf.inputs["Roughness"].default_value = 0.6
    bsdf.inputs["Metallic"].default_value = 0.0
    body.data.materials.clear()
    body.data.materials.append(mat)
    for img in list(bpy.data.images):
        if img is not image and img.users == 0:
            bpy.data.images.remove(img)


def build_rig(body):
    h = humanoid.Humanoid(NAME + "_rodin", HEIGHT, "hero")
    h.j = {k: Vector((x * HEIGHT, 0.0, z * HEIGHT)) for k, (x, z) in JOINTS.items()}
    h.j["toe"].y = -0.105 * HEIGHT

    def side(key, s, base=h.side):
        p = base(key, s)
        if key in SIDE_X:
            p.x = SIDE_X[key][0 if s > 0 else 1]
        if key in JOINT_Y:
            p.y = JOINT_Y[key]
        return p
    h.side = side
    table = humanoid._bone_table(h)
    if HEAD_END_Z:
        head, _, parent = table["Head_end"]
        table["Head_end"] = ((head[0], head[1], HEAD_END_Z), (head[0], head[1], HEAD_END_Z + 0.03), parent)
    arm = humanoid.make_armature(NAME + "_Armature", table)
    bpy.ops.object.select_all(action="DESELECT")
    body.select_set(True)
    arm.select_set(True)
    bpy.context.view_layer.objects.active = arm
    bpy.ops.object.parent_set(type="ARMATURE_AUTO")
    return h, arm, table


def bone_distance(table, name, point):
    head, tail, _ = table[name]
    a, b = Vector(head), Vector(tail)
    ab = b - a
    t = max(0.0, min(1.0, (point - a).dot(ab) / max(ab.length_squared, 1e-9)))
    return (point - (a + ab * t)).length


def fix_loose_parts(body, table):
    """Parts the heat solver could not reach (the mace) follow the nearest bone as a rigid piece."""
    # the mesh is split along UV seams: join vertices that share a position before looking for separate pieces
    verts = body.data.vertices
    key_of = {}
    weld = [key_of.setdefault(tuple(round(c, 4) for c in v.co), len(key_of)) for v in verts]
    parent = list(range(len(key_of)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for e in body.data.edges:
        ra, rb = find(weld[e.vertices[0]]), find(weld[e.vertices[1]])
        if ra != rb:
            parent[ra] = rb
    groups = {}
    for i in range(len(verts)):
        groups.setdefault(find(weld[i]), []).append(i)
    islands = list(groups.values())
    islands.sort(key=len, reverse=True)
    print("islands", [len(i) for i in islands[:6]], "of", len(islands))
    names = [b for b in table if b not in ("Root", "Head_end")]
    for island in islands[1:]:
        if len(island) < 30 or len(island) > 3000:
            continue
        centre = sum((body.data.vertices[i].co for i in island), Vector()) / len(island)
        best = min(names, key=lambda n: bone_distance(table, n, centre))
        for i in island:
            for g in list(body.data.vertices[i].groups):
                body.vertex_groups[g.group].remove([i])
        body.vertex_groups[best].add(island, 1.0, "REPLACE")
        print("rigid island", len(island), "->", best, tuple(round(c, 2) for c in centre))
    # any vertex still without weights follows its nearest bone
    for v in body.data.vertices:
        if not v.groups:
            best = min(names, key=lambda n: bone_distance(table, n, v.co))
            body.vertex_groups[best].add([v.index], 1.0, "REPLACE")


def smooth(x, lo, hi):
    t = max(0.0, min(1.0, (x - lo) / (hi - lo)))
    return t * t * (3 - 2 * t)


def joint_x(key):
    """(left, right) x of a joint in metres."""
    if key in SIDE_X:
        return SIDE_X[key]
    return (JOINTS[key][0] * HEIGHT, -JOINTS[key][0] * HEIGHT)


def _arm_bone_names(table):
    return [n for n in table if n.startswith(("UpperArm_", "Forearm_", "Hand_"))]


def _leg_bone_names(table):
    return [n for n in table if n.startswith(("Thigh_", "Shin_", "Foot_"))] + ["Hips"]


def leg_weights(body, table):
    """Heat weights smear the two legs and the skirt into each other, so below the hips weights follow the
    side and the height (thigh, shin, foot) instead; they fade into the heat weights at the hips.
    With a skirt the two sides blend over a wide band and part of the weight stays on the hips, so the
    cloth does not tear between the legs and does not swing as far as they do.

    A-pose hands often hang at hip height: those vertices must stay on the arms, not become skirt."""
    hip, knee, ankle = (JOINTS[k][1] * HEIGHT for k in ("hip", "knee", "ankle"))
    names = {g.index: g.name for g in body.vertex_groups}
    band = 0.22 if SKIRT else 0.04
    arms = _arm_bone_names(table)
    legs = _leg_bone_names(table)
    for v in body.data.vertices:
        if arms and legs:
            d_arm = min(bone_distance(table, n, v.co) for n in arms)
            d_leg = min(bone_distance(table, n, v.co) for n in legs)
            if d_arm <= d_leg:
                continue
        u = smooth(v.co.z, hip - 0.10, hip + 0.06)  # 1: heat weights
        if u >= 1.0:
            continue
        thigh = smooth(v.co.z, knee - 0.06, knee + 0.06)
        rest = 1.0 - thigh
        foot_w = rest * (1.0 - smooth(v.co.z, ankle + ANKLE_BLEND[0], ankle + ANKLE_BLEND[1]))
        shin = rest - foot_w
        # which leg: the nearer of the two leg axes at this height
        t = max(0.0, min(1.0, (v.co.z - ankle) / (hip - ankle)))
        axis_l = joint_x("ankle")[0] + (joint_x("hip")[0] - joint_x("ankle")[0]) * t
        axis_r = joint_x("ankle")[1] + (joint_x("hip")[1] - joint_x("ankle")[1]) * t
        left = smooth(abs(v.co.x - axis_r) - abs(v.co.x - axis_l), -band, band)
        custom = {}
        hips_share = 0.5 * smooth(v.co.z, ankle + 0.10, ankle + 0.30) if SKIRT else 0.0
        if SKIRT:  # a train dragging behind the feet stays with the hips instead of following the foot
            hips_share = max(hips_share, smooth(v.co.y, 0.10, 0.22))
        if SKIRT and SKIRT_HEM is not None:  # a short tunic: the bare shin below the hem is all leg
            hips_share *= smooth(v.co.z, SKIRT_HEM - 0.04, SKIRT_HEM + 0.02)
        for side, sw in (("L", left), ("R", 1.0 - left)):
            for bone, w in (("Thigh_", thigh), ("Shin_", shin), ("Foot_", foot_w)):
                custom[bone + side] = custom.get(bone + side, 0.0) + w * sw * (1.0 - hips_share)
        custom["Hips"] = hips_share
        mixed = {names[g.group]: g.weight * u for g in v.groups}
        for bone, w in custom.items():
            mixed[bone] = mixed.get(bone, 0.0) + w * (1.0 - u)
        for g in list(v.groups):
            body.vertex_groups[g.group].remove([v.index])
        for bone, w in mixed.items():
            if w > 0.002:
                body.vertex_groups[bone].add([v.index], w, "REPLACE")


def arm_weights(body, table):
    """Put A-pose hands back on the arm chain when the skirt pass stole them.

    Only vertices that still carry mostly hip/leg weight while sitting nearer an arm than a leg are
    rewritten: a blanket rebind of every arm-near vertex pulled the tunic and shoulders onto the
    arms and collapsed the swim pose."""
    arms = _arm_bone_names(table)
    legs = _leg_bone_names(table)
    if not arms or not legs:
        return
    names = {g.index: g.name for g in body.vertex_groups}
    fixed = 0
    for v in body.data.vertices:
        current = {names[g.group]: g.weight for g in v.groups}
        leg_w = sum(current.get(n, 0.0) for n in legs)
        arm_w = sum(current.get(n, 0.0) for n in arms)
        if arm_w >= leg_w:
            continue
        d_arm = min(bone_distance(table, n, v.co) for n in arms)
        d_leg = min(bone_distance(table, n, v.co) for n in legs)
        if d_arm > d_leg or d_arm > 0.20:
            continue
        side = "L" if v.co.x >= 0.0 else "R"
        chain = [f"UpperArm_{side}", f"Forearm_{side}", f"Hand_{side}"]
        dists = [max(bone_distance(table, b, v.co), 1e-4) for b in chain]
        inv = [1.0 / d for d in dists]
        total = sum(inv) or 1.0
        for g in list(v.groups):
            body.vertex_groups[g.group].remove([v.index])
        for bone, w in zip(chain, inv):
            body.vertex_groups[bone].add([v.index], w / total, "REPLACE")
        fixed += 1
    print("arm_weights vertices", fixed)


def spatial_smooth(body, radius_below, radius_above, split_z, iterations=3, blend=0.7, keep=6, table=None):
    """Layered cloth (overlapping skirt flounces) and arms close to the torso get unrelated weights from the
    heat solver, so the layers drift apart when the body moves. Averaging weights of vertices that are near
    each other in space, whatever surface they are on, keeps neighbouring layers moving together.

    Vertices nearer an arm than a leg are left alone: below the hips they sit next to the skirt, and
    averaging would glue the hands to Thigh/Hips again."""
    from mathutils.kdtree import KDTree
    verts = body.data.vertices
    names = {g.index: g.name for g in body.vertex_groups}
    freeze = set()
    if table is not None:
        arms = _arm_bone_names(table)
        legs = _leg_bone_names(table)
        if arms and legs:
            for v in verts:
                if min(bone_distance(table, n, v.co) for n in arms) <= min(bone_distance(table, n, v.co) for n in legs):
                    freeze.add(v.index)
    tree = KDTree(len(verts))
    for v in verts:
        tree.insert(v.co, v.index)
    tree.balance()
    neighbours = []
    for v in verts:
        radius = radius_below if v.co.z < split_z else radius_above
        neighbours.append([i for _, i, _ in tree.find_range(v.co, radius)])
    weights = [{names[g.group]: g.weight for g in v.groups} for v in verts]
    for _ in range(iterations):
        new = []
        for i, w in enumerate(weights):
            if i in freeze:
                new.append(dict(w))
                continue
            acc = {}
            for j in neighbours[i]:
                for bone, x in weights[j].items():
                    acc[bone] = acc.get(bone, 0.0) + x / len(neighbours[i])
            out = {b: w.get(b, 0.0) * (1 - blend) + acc.get(b, 0.0) * blend for b in set(w) | set(acc)}
            top = sorted(out.items(), key=lambda kv: -kv[1])[:keep]
            total = sum(x for _, x in top) or 1.0
            new.append({b: x / total for b, x in top})
        weights = new
    for g in list(body.vertex_groups):
        body.vertex_groups.remove(g)
    groups = {n: body.vertex_groups.new(name=n) for n in names.values()}
    for i, w in enumerate(weights):
        for bone, x in w.items():
            if x > 0.005:
                groups[bone].add([i], x, "REPLACE")


def unify_seams(body):
    """The mesh is split along UV seams; smoothing treats the two copies of a seam vertex differently, which would
    tear the surface when it moves. Copies at the same position get the same (averaged) weights."""
    names = {g.index: g.name for g in body.vertex_groups}
    by_pos = {}
    for v in body.data.vertices:
        by_pos.setdefault(tuple(round(c, 4) for c in v.co), []).append(v.index)
    for indices in by_pos.values():
        if len(indices) < 2:
            continue
        acc = {}
        for i in indices:
            for g in body.data.vertices[i].groups:
                acc[names[g.group]] = acc.get(names[g.group], 0.0) + g.weight / len(indices)
        for i in indices:
            for g in list(body.data.vertices[i].groups):
                body.vertex_groups[g.group].remove([i])
            for bone, w in acc.items():
                if w > 0.002:
                    body.vertex_groups[bone].add([i], w, "REPLACE")


def add_star_disc(body):
    """An eight-pointed star in a disc (Ishtar's emblem) standing upright over the head, carried by the Head bone."""
    if not STAR_DISC:
        return
    top = [v.co for v in body.data.vertices if v.co.z > HEIGHT - 0.3]
    cx = sorted(c.x for c in top)[len(top) // 2]
    cy = sorted(c.y for c in top)[len(top) // 2]
    z_top = STAR_DISC.get("base_z", max(c.z for c in top))  # the head itself, when horns rise higher
    radius, points = STAR_DISC["radius"], STAR_DISC.get("points", 8)
    thick = radius * 0.16
    bm = bmesh.new()
    outline = []
    for k in range(points * 2):
        a = math.pi * k / points
        r = radius if k % 2 == 0 else radius * 0.55
        outline.append((r * math.sin(a), r * math.cos(a)))
    ring = [bm.verts.new((cx + x, cy - thick / 2, z_top + STAR_DISC.get("lift", 0.0) + radius + y)) for x, y in outline]
    face = bm.faces.new(ring)
    back = bmesh.ops.extrude_face_region(bm, geom=[face])
    moved = [e for e in back["geom"] if isinstance(e, bmesh.types.BMVert)]
    bmesh.ops.translate(bm, vec=(0, thick, 0), verts=moved)
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    # a raised disc in the middle of the star
    disc = bmesh.ops.create_cone(bm, cap_ends=True, segments=24, radius1=radius * 0.36, radius2=radius * 0.36, depth=thick * 1.6,
                                 matrix=__import__("mathutils").Matrix.Translation((cx, cy - thick * 0.2, z_top + STAR_DISC.get("lift", 0.0) + radius))
                                 @ __import__("mathutils").Matrix.Rotation(math.pi / 2, 4, "X"))
    me = bpy.data.meshes.new("star_disc")
    bm.to_mesh(me)
    bm.free()
    obj = bpy.data.objects.new("star_disc", me)
    bpy.context.scene.collection.objects.link(obj)
    mat = bpy.data.materials.new("star_gold")
    mat.use_nodes = True
    bsdf = mat.node_tree.nodes["Principled BSDF"]
    bsdf.inputs["Base Color"].default_value = (0.95, 0.68, 0.16, 1.0)
    bsdf.inputs["Metallic"].default_value = 0.85
    bsdf.inputs["Roughness"].default_value = 0.32
    me.materials.append(mat)
    obj.vertex_groups.new(name="Head").add(list(range(len(me.vertices))), 1.0, "REPLACE")
    bpy.ops.object.select_all(action="DESELECT")
    obj.select_set(True)
    body.select_set(True)
    bpy.context.view_layer.objects.active = body
    bpy.ops.object.join()


def _gold_material(name="star_gold", colour=(0.95, 0.68, 0.16, 1.0), metallic=0.85, roughness=0.32):
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    mat.use_nodes = True
    bsdf = mat.node_tree.nodes["Principled BSDF"]
    bsdf.inputs["Base Color"].default_value = colour
    bsdf.inputs["Metallic"].default_value = metallic
    bsdf.inputs["Roughness"].default_value = roughness
    return mat


def add_quiver(body):
    """A leather quiver with arrows slung on the back, carried by the Chest bone."""
    if not QUIVER:
        return
    from mathutils import Matrix
    back = [v.co for v in body.data.vertices if abs(v.co.z - QUIVER["z"]) < 0.08 and abs(v.co.x - QUIVER["x"]) < 0.1]
    back_y = max(c.y for c in back)
    length, radius = QUIVER["length"], 0.05
    tilt = QUIVER.get("tilt", 0.35)  # radians; the top leans towards the shoulder it hangs from
    sign = 1.0 if QUIVER["x"] >= 0 else -1.0
    centre = Vector((QUIVER["x"], back_y + radius + 0.02, QUIVER["z"]))
    rot = Matrix.Rotation(-sign * tilt, 4, "Y")
    bm = bmesh.new()
    bmesh.ops.create_cone(bm, cap_ends=True, segments=16, radius1=radius * 0.85, radius2=radius, depth=length,
                          matrix=Matrix.Translation(centre) @ rot)
    leather = len(bm.faces)
    # gold rims, and arrows with red fletching standing out of the top
    rims = []
    for dz, rr in ((length * 0.5 - 0.02, radius * 1.08), (-length * 0.5 + 0.03, radius * 0.95)):
        r = bmesh.ops.create_cone(bm, cap_ends=True, segments=16, radius1=rr, radius2=rr, depth=0.035,
                                  matrix=Matrix.Translation(centre) @ rot @ Matrix.Translation((0, 0, dz)))
        rims += [f for f in bm.faces if all(v in r["verts"] for v in f.verts)]
    arrow_faces = []
    for k, (ox, oy) in enumerate(((0, 0), (0.022, 0.012), (-0.022, 0.014), (0.012, -0.022), (-0.012, -0.02))):
        base = Matrix.Translation(centre) @ rot @ Matrix.Translation((ox, oy, length * 0.5))
        r = bmesh.ops.create_cone(bm, cap_ends=True, segments=6, radius1=0.006, radius2=0.006, depth=0.22 - 0.02 * k,
                                  matrix=base @ Matrix.Translation((0, 0, (0.22 - 0.02 * k) / 2 - 0.02)))
        f = bmesh.ops.create_cone(bm, cap_ends=True, segments=6, radius1=0.022, radius2=0.004, depth=0.07,
                                  matrix=base @ Matrix.Translation((0, 0, (0.22 - 0.02 * k) - 0.05)))
        arrow_faces += [fc for fc in bm.faces if all(v in r["verts"] or v in f["verts"] for v in fc.verts)]
        rims += [fc for fc in bm.faces if all(v in f["verts"] for v in fc.verts)]
    me = bpy.data.meshes.new("quiver")
    bm.to_mesh(me)
    bm.free()
    leather_mat = bpy.data.materials.new("quiver_leather")
    leather_mat.use_nodes = True
    leather_mat.node_tree.nodes["Principled BSDF"].inputs["Base Color"].default_value = (0.32, 0.17, 0.08, 1.0)
    leather_mat.node_tree.nodes["Principled BSDF"].inputs["Roughness"].default_value = 0.7
    wood = bpy.data.materials.new("arrow_wood")
    wood.use_nodes = True
    wood.node_tree.nodes["Principled BSDF"].inputs["Base Color"].default_value = (0.62, 0.45, 0.25, 1.0)
    red = bpy.data.materials.new("arrow_red")
    red.use_nodes = True
    red.node_tree.nodes["Principled BSDF"].inputs["Base Color"].default_value = (0.6, 0.05, 0.04, 1.0)
    for m in (leather_mat, _gold_material(), wood, red):
        me.materials.append(m)
    # material index per face: 0 leather, 1 gold rims, 2 arrow shafts, 3 fletching
    shaft_set = set(i for i in range(len(me.polygons)))
    for poly in me.polygons:
        poly.material_index = 0
    obj = bpy.data.objects.new("quiver", me)
    bpy.context.scene.collection.objects.link(obj)
    # classify polygons by position instead of by bmesh face identity (faces are renumbered by to_mesh)
    top_z = length * 0.5
    for poly in me.polygons:
        local = (rot.inverted() @ (poly.center - centre))
        if local.z > top_z + 0.01:
            poly.material_index = 2 if (local.x ** 2 + local.y ** 2) ** 0.5 < 0.04 and poly.area < 0.002 else 3
        elif abs(local.z - (top_z - 0.02)) < 0.022 or abs(local.z - (-top_z + 0.03)) < 0.022:
            poly.material_index = 1
    obj.vertex_groups.new(name="Chest").add(list(range(len(me.vertices))), 1.0, "REPLACE")
    bpy.ops.object.select_all(action="DESELECT")
    obj.select_set(True)
    body.select_set(True)
    bpy.context.view_layer.objects.active = body
    bpy.ops.object.join()


def add_face(h, body):
    """Blink and mouth blend shapes (vrc_blink, vrc_v_*), built around the eyes and the mouth with a smooth falloff, so
    nothing tears at the edge of the region."""
    if not FACE:
        return

    def surface(p):
        """(x, z) -> the point on the front of the face."""
        if len(p) == 3:
            return Vector(p)
        near = [v.co.y for v in body.data.vertices if abs(v.co.x - p[0]) < 0.04 and abs(v.co.z - p[1]) < 0.04 and v.co.y < 0.15]
        return Vector((p[0], min(near) + 0.004, p[1]))
    eyes = [surface(e) for e in FACE["eyes"]]
    mc = surface(FACE["mouth"])
    me = body.data
    body.shape_key_add(name="Basis", from_mix=False)
    front = mc.y + 0.05

    def falloff(d, rx, ry, rz):
        r2 = (d.x / rx) ** 2 + (d.y / ry) ** 2 + (d.z / rz) ** 2
        t = max(0.0, 1.0 - r2)
        return t * t * (3 - 2 * t)

    def make(name, fn):
        key = body.shape_key_add(name=name, from_mix=False)
        for i, v in enumerate(me.vertices):
            if v.co.y < front:
                key.data[i].co = fn(v.co)

    def blink(co):
        for e in eyes:
            w = falloff(co - e, 0.034, 0.05, 0.018)
            if w > 0:
                return Vector((co.x, co.y, e.z + (co.z - e.z) * (1 - 0.9 * w)))
        return co

    make("vrc_blink", blink)
    # name: (width scale, jaw drop in metres, lips pushed forward in metres)
    mouths = {"aa": (1.0, 0.016, 0.0), "oh": (0.72, 0.009, -0.004), "ee": (1.2, 0.003, 0.0), "ou": (0.58, 0.005, -0.006),
              "ih": (1.08, 0.004, 0.0), "dd": (1.0, 0.007, 0.0), "ch": (0.85, 0.003, 0.0)}
    for name, (sx, drop, push) in mouths.items():
        def mouth(co, sx=sx, drop=drop, push=push):
            d = co - mc
            w = falloff(d, 0.04, 0.05, 0.026)
            if w <= 0:
                return co
            lower = 1.0 if d.z < 0 else 0.25
            return Vector((mc.x + d.x * (1 + (sx - 1) * w), co.y + push * w, co.z - drop * w * lower))
        make("vrc_v_" + name, mouth)


def bind_held_item(body):
    if not HELD:
        return
    bone = HELD["bone"]
    """The mace sticks out beside the right arm: it is held, so it moves rigidly with the hand."""
    held = [v.index for v in body.data.vertices if is_held(v.co)]
    for i in held:
        for g in list(body.data.vertices[i].groups):
            body.vertex_groups[g.group].remove([i])
    body.vertex_groups[bone].add(held, 1.0, "REPLACE")
    print("held item vertices", len(held), "->", bone)


def main():
    body = import_mesh()
    normalise(body)
    body = decimate(body)
    simplify_material(body)
    body.name = NAME
    h, arm, table = build_rig(body)
    fix_loose_parts(body, table)
    if not os.environ.get("RODIN_NO_LEG_WEIGHTS"):
        leg_weights(body, table)
    humanoid._smooth_weights(body, iterations=2, blend=0.4, keep=INFLUENCES)
    if SPATIAL:
        spatial_smooth(body, SPATIAL[0], SPATIAL[1], JOINTS["hip"][1] * HEIGHT + 0.05, keep=INFLUENCES, table=table)
    # After skirt/leg passes: put any remaining skirt-weighted hands back on the arms.
    arm_weights(body, table)
    bind_held_item(body)
    unify_seams(body)
    add_star_disc(body)
    add_quiver(body)
    add_face(h, body)
    bpy.context.view_layer.objects.active = arm
    h.arm_swing = {"L": ARM_SWING_SIDES.get("L", ARM_SWING), "R": ARM_SWING_SIDES.get("R", ARM_SWING)}
    humanoid.humanoid_animations(h, arm, stride=STRIDE, run=bool(CONFIG.get("run")))
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    humanoid.export_glb(OUT)
    print("exported", OUT, os.path.getsize(OUT), "bytes", len(body.data.polygons), "faces")


main()
